from typing import List

class FloorCleaner:
    def findMinimumCleaningTime(self, N: int, M: int, workerSegments: List[List[int]]) -> int:
        workers = self.sortByStartTime(workerSegments)
        time = 0
        observed = []
        for worker in workers:
            segmentEnd, delay, l = worker[1], worker[0] - delay[0], 0
            while segmentEnd <= N and (l, l + segmentEnd - 1) not in observed:
                time += delay[1]
                observed.append((l, l + segmentEnd - 1))
                elapsed = min(delay[1], (l + segmentEnd - 1) - segmentEnd + 1)
                delay[0], delay[1] = max(0, delay[0] - elapsed), min(delay[1], N - (l + segmentEnd - 1))
                segmentEnd += 1
            if segmentEnd > N:
                return -1
        return time

    def sortByStartTime(self, workerSegments: List[List[int]]) -> List[List[int]]:
        return sorted(workerSegments, key=lambda x: x[1][1] - x[1][0])

