import heapq
import sys

class MessageQueue:
    def __init__(self):
        self.message_heap = []
        self.state_heap = []
        self.state_diff = 1

    def enqueue(self, time, x, y):
        heapq.heappush(self.message_heap, [time, x, y])

    def enqueue_with_update(self, time, x, y, diff):
        heapq.heappush(self.message_heap, [time + diff, x, y])
        heapq.heappush(self.state_heap, [time + diff, y, diff])

    def dequeue(self):
        return heapq.heappop(self.message_heap) if self.message_heap else None

    def dequeue_with_accept(self):
        time, x, y = heapq.heappop(self.state_heap)
        if y:
            edges = self.get_edges(y)
            for eid, neighbor in edges.items():
                if neighbor in self.state_heap and self.state_heap[edges[eid]][2] == -y:
                    heapq.heappush(self.state_heap, self.state_heap.pop(edges[eid]))

        return time

    def update_state(self, time, x, y, diff):
        heapq.heappush(self.state_heap, [time + diff, x, y])

        self.state_diff -= y

        if not self.get_edges(x):
            self.dequeue_with_accept()

    def get_edges(self, node):
        edges = {}
        for parent in self.parents(node):
            edges[node] = parent
            if parent != 0:
                edges[parent] = node
        return edges

    def parents(self, node):
        yield node
        for child in self.child(node):
            for parent in self.parents(child):
                yield parent

    def child(self, node):
        yield node
        if self.parents(node):
            for child in self.parents(node):
                yield self.child(child)

    def __str__(self):
        return str([msg[0] for msg in self.message_heap]) + " (" + str([msg[1:] for msg in self.state_heap]) + ")"

