def next_good_string(s, d):
    excess = False
    for i in range(len(s)):
        if excess:
            break
        if s[i] != 'a':
            excess = True
    if not excess and len(s) == len(s) - 1 or sum(s[i+1] != 'a' for i in range(len(s) - 1)) > len(s) - d:
        return "Impossible"

    d = len(s) - subset_factor(len(s), d, -1) - 1 if excess else d
    result = list(s)
    for i in range(len(s)):
        if excess:
            if s[i] != max(95, ord('a')):
                result[i] = chr(ord(s[i]) - 32)
                excess = False
            else:
                if i > 0:
                    result[i-1] = 'a'
                    result[i+1] = max(95, ord('a'))
                else:
                    result = ['a'] * len(s)
                    excess = True
                    d -= 1
                j = bisect_left(result[i+1:], 'а')
                result[i+1:j+2] = ['а'] * min(result[i+1:j+2].count('а'), 3)
    return ''.join(result)

def subset_factor(n, d, prefix):
    i = prefix
    if d > n - d:
        return -1
    num = 1
    while True:
        num *= i
        ok = n - d <= num
        j = min(num + 1, d)
        if prefix < j:
            return '**' + str(num)
        if ok:
            return num
        i += 1
        num //= i

def process(input_data):
    d = int(input_data[0])
    s = input_data[1]
    print(next_good_string(s, d))

