# Function to sort out suppossitious superposed conditions (edge here):
def remove_redundant_edges(edges, conditions):
    for i in range(len(edges)):
        exists = [True for j in range(i+1) if edges[j] in conditions]
        superposed = [True for j in range(len(edges)) if edges[j] in conditions and not exists]
        sort = sorted(ind for ind in superposed if ind <= i)
        if len(sort) > 1:
            if sort[1] - sort[0] == 2:
                edges.pop(sort[0])
                edges.pop(sort[1])

def check_turtle_optimization(edges, conditions, n):          
    nodes = defaultdict(int)
    stack = [0]
    factFreq, fact = [1] * (n-1), defaultdict(lambda: 0)
    turtle = []
    for condition in conditions:
        node1, node2 = condition[0], condition[1]
        if nodes[node1] < 2 and node2 not in turtle:
            turtle.append(node2)
            nodes[node2] = 2
            contribute = factFreq[turtle[-2]] * fact[turtle[-1]] 
            fact[turtle[-1]] += factFreq[turtle[-1]] 
            if condition[2] == contribute:      
                stack += list(range(nodes[node2], n))                
                nodes[node2] = n
    if n - 1 in fact:
        return len(stack) == len(set(stack))
    else:
        return list(range(len(stack))) == list(set(stack)) and stack[-1] == n - 1

