from collections import defaultdict

class MaxTree():
    def __init__(self, n):
        self.max_leaf_to_root = [-1] * n
        self.tree = [-1] * n

    def parent(self, u):
        return self.tree[u]

    def max_paths(self):
        m = 0
        for i in range(n): 
            if self.max_leaf_to_root[i] > m: 
                m = self.max_leaf_to_root[i]
        return m

    def query(self, u):
        last_path = self.max_paths()
        min_path = self.tree[self.parent(u)-1]
        while u:
            path = max(min_path, self.max_paths())
            if last_path > path:
                self.max_leaf_to_root[u] = -1
                break
            elif last_path < path:
                self.max_leaf_to_root[u] = max(min(last_path, 
                                                    min_path - 1), self.max_leaf_to_root[self.parent(u)-1]) + 1
                break
            else:
                self.max_leaf_to_root[u] = -1
                break
            u = self.parent(u)
        return self.max_leaf_to_root[u]

def predictAnswer(node_id, query_time, message_time):
    n = len(message_time) + 1
    tree = MaxTree(n)

    message_index_map = defaultdict(int)
    for d, t in enumerate(message_time):
        message_index_map[t] = d

    time = 0
    current_node_runner = 1
    while time < query_time:
        if message_index_map[time] != message_index_map[time+1]:
            current_node_runner += 1
        time += 1
        answer = tree.query(current_node_runner)
        if answer == -1:
            messagebox = query_time
        else:
            messagebox = query_time - answer
        print(f"Node: {node_id}, Time: {messagebox}")
