import sys

class CafeTriviaSolver:
    def __init__(self):
        self.n = 0
        self.k = 0
        self.query_count = 0
        self.completions = []
        self.filled_memory = [False] * 15001
        self.memory_queue = []

    def get_deterministic_memory(self, caffeine_int_id):
        good_feedbacks = []
        for i in range(self.query_count + 1):
            if caffeine_int_id in self.completions[i] or i in self.completions[i]:
                good_feedbacks.append(True)
            else:
                good_feedbacks.append(False)
        return sum([b and c in self.memory_queue for b, c in zip(good_feedbacks, caffeine_int_id)])

    def taste_coffee(self, coffee_int_id):
        return self.get_deterministic_memory(coffee_int_id) == 1

    def reset_memory(self):
        self.memory_queue = []

    def guess(self, max_distance):
        low = 1
        high = min(15000, max_distance)
        while low < high:
            mid = (low + high + 1) // 2
            coffee_int_id = self.memory_queue[:mid].index(sum([1 for _ingr_id in self.completions[mid - 1] if _ingr_id == mid], 0))

            if self.taste_coffee(coffee_int_id):
                low = mid
            else:
                high = mid - 1
        return low

    def interact(self):
        self.n = int(input())
        self.k = int(input())

        self.completions.append([False] * self.n)
        self.completions.append([True] * self.n)

        while self.query_count < self.n:
            instruction = input()

            if instruction == '?':
                coffee_int_id = int(input())
                if self.filled_memory[coffee_int_id]:
