                idx = (j + 1 - matrix[i].index('a')) % (m - 1)
                matrix[i][j] = ''.join(max(k, 'a') for k in matrix[i][j:j+idx]).ljust(m) + ' '

    # Map each letter 'a' to '.' and rest to 'abcdefghijklmnopqrstuvwxyz'
    lowercase = [' ']
    nums = [0]
    for row in matrix:
        for ch in row:
            if ch != '.':
                lowercase.append(ch)
        nums.extend([i for i in range(0, n)])

    # Initial positions for each query char
    letter_pos = {letter: idx for idx, letter in enumerate(lowercase)}
    char_row_pos = [[] for _ in range(m)]

    for i in range(n):
        for j in range(m):
            char = matrix[i][j:j+1]
            if char != ' ':
                char_row_pos[letter_pos[char]].append(i)
                if i == 0 or j != m-1:
                    char_row_pos[letter_pos[char] + 1].append(i + 1)

    char_num = []
    for i in range(m):
        for j in char_row_pos[i] + char_row_pos[i+1]:
            char_num.append(nums[j])

    return min_operations_recursive(char_num)

def min_operations_recursive(char_num):
    if len(char_num) == 1:
        return 0

    char_left, tot_to_find = char_num[1], 0
    openness, min_count, open_loc = 0, float('inf'), []
    for i in range(len(char_num) - 2, -1, -1):
        to_decrement = char_num[i+2] - char_num[i+1] - 1
        char_right = char_num[i + 2]
        loc = (tot_to_find - to_decrement) // (char_left - char_right)
        if loc:
            open_loc.append(i)
            openness += loc
            char_num.remove(char_num[i + 2] + 1)
        tot_to_find += (char_left - char_right)

    if not openness:
        return open_loc[0] + min_operations_recursive(char_num)
    else:
        return 1 + open_loc[0] + min_operations_recursive(char_num)

