from math import ceil, floor

def get_path_points(n, edges):
    path_length = 1
    while n >= 2 * path_length:
        path_length += 1
    points = []
    for i in range(1, floor(n / path_length) + 1):
        remaining_n = n
        while remaining_n >= pow(2, i):
            remaining_n -= pow(2, i)
            path_income = pow(2, i - 1)
        for _ in range(path_length):
            points.append((i, path_income, i + path_income))
            if path_income >= n:
                path_income = 0
            else:
                path_income += 1
        path_income = 0
        if path_length % 2 == 1 and remaining_n >= pow(2, floor(path_length / 2)):
            points.append((i + 1, path_income, i))
            n -= pow(2, floor(path_length / 2))
        else:
            first_node = n - min(list(map(lambda x: x[0], points))[-1]) - 1
            last_node = n - n % pow(2, floor(path_length / 2)) - 1
            for n_i in range(first_node, last_node + 1):
                if remaining_n < pow(2, i) and i < path_length // 2:
                    points.append((i, floor(remaining_n * (path_length / path_length // 2)), i + floor(remaining_n * (path_length / path_length // 2))))
                else:
                    points.append((i, floor(remaining_n * (pow(2, i + 1) / (path_length - i))), i + pow(2, i + 1)))
                remaining_n -= pow(2, i)
    return points

n = int(input())
