def apply_paint_operation(b, r, LtoR=1):
    if LtoR:
        bisect.insort_left(b, r)
    else:
        bisect.insort_left(b, LtoR)

def get_sum_colorfulness(L, R, b):
    left, right = L-1, R
    area_front = 0
    area_bak = 0
    l_idx, b_idx = bisect.bisect_left(b, L-1), bisect.bisect_left(b, R)
    count = 0
    for idx in range(l_idx, 0):
        if b[idx] == L-1:
            break
        if b[idx] < L-1:
            area_front += 1
        else:
            area_bak -= 1
            l_idx -= 1
    for idx in range(r+1, len(b)):
        if b[idx] == R:
            break
        if b[idx] > R:
            continue
        area_bak += 1
        r += 1
    for idx in range(l_idx):
        if b[idx] == r+1:
            break
        if b[idx] == L-1:
            area_bak += 1
        else:
            area_front -= 1
            b_idx -= 1
    while left != 0 or right != len(b)-1:
        if left == 0:
            if right == len(b)-1:
                break
            right += 1
        if right == len(b)-1:
            if left == 0:
                break
            left -= 1
        final_count = area_front + area_bak
        if left == 0:
            return final_count
        if right == len(b) - 1:
            return final_count
        if b[left-1] > b[right+1]:
            area_back = (b[left-1] - L+ 1) if left-1 > 0 else L-1
            area_front -= (b[left-1] - L+ 1)
            if b[left-1] == left:
                left -= 1
        else:
            area_back = (b[right+1] - R) if right+1 < len(b) else R - b[right]
            area_bak -= (b[right+1] - R)
            if b[right+1] == right:
                right += 1
        left -= len(b[b_idx:])
        right += len(b[b_idx:])
    return area_bak

