    total_change = diff * (r - l + 1) - diff * diff
    return total_change

def process_operation(l, r, type_val):
    if type_val == 1:
        x = int(input().strip())
        return apply_paint(l, r, x)
    else:
        l, r = map(int, input().strip().split())
        return sum(i - l + 1 for i in range(l, r + 1))

n, m = map(int, input().strip().split())
prefix_sum = [0]
total_change = 0

for i in range(m):
    type_val = int(input().strip())
    if type_val == 1:
        total_change += process_operation(1, n, type_val)
    else:
        l, r = map(lambda x: int(x) - 1, input().strip().split())
        prefix_sum.append(prefix_sum[-1] + process_operation(l, r, type_val))
    print(prefix_sum[-1] - total_change + total_change)

