from collections import defaultdict

def min_operations(matrix, query):
    row = len(matrix)
    col = len(matrix[0])
    gap = defaultdict(int)
    for cq in query:
        for j in range(col):
            c = cq[j]
            if c in gap:
                gap[c] -= 1
                if gap[c] == 0:
                    del gap[c]
            gap[c] += 1

    min_changes = float('inf')
    for i in range(row):
        if all(val == 0 for val in gap.values()):
            min_changes = min(min_changes, i)

    if min_changes == float('inf'):
        return -1
    else:
        return min_changes

# Example usage:
n, m, q = map(int, input().split())
matrix = [input() for _ in range(n)]
query_strings = [input().strip() for _ in range(q)]
for query in query_strings:
    print(0 if min_operations(matrix, [query]) == float('inf') else min_operations(matrix, [query]))
